    D2Common::ITEMS::Items::ITEM_EditItemData_eItemFlag(pItem, eSavedItemFlag, 1);
    sPacket.nPacketSize = (uint8_t)nTotalPacketLen;
    SCMD_QueuePacketForClient(&sPacket.nPacketId, (uint8_t)nTotalPacketLen, pClient);
