// Sends opcode 0x3E item-stat-update packet to pClient. Encodes unit GUID, equipped flag, stat ID (9 bits), stat value (variable size), and stat layer/count (8 or 16 bits) into a bit-buffer inside a 34-byte stack packet, then sends it.
void __fastcall NET_D2GS_SERVER_Send_0x3E_UpdateItemStats(D2ClientStrc * pClient, D2UnitStrc * pUnit, char bIsEquipped, int32_t nStatId, uint32_t nStatValue, uint16_t nStatLayerOrCount) {
    uint32_t dwUnitGUID;
    D2BitBufferStrc bitBuf;
    uint8_t aPacket[34];
    int32_t nBitPos;
    memset(aPacket + 4, 0, 30 * sizeof(aPacket[0]));
    aPacket[0] = 0x3e;
    aPacket[1] = 0;
    aPacket[2] = 0;
    aPacket[3] = 0;
    Fog::BitBuffer::InitBitBuffer(&bitBuf, aPacket + 2, 0x20);
    if (!pUnit) {
      dwUnitGUID = -1;
    } else {
      dwUnitGUID = pUnit->nUnitGUID;
    }

    Server::ServerCmd::WriteValueBySize(&bitBuf, dwUnitGUID);
    Fog::BitBuffer::WriteValueToBitBuffer(&bitBuf, (uint32_t)(bIsEquipped != '\0'), 1);
    Fog::BitBuffer::WriteValueToBitBuffer(&bitBuf, nStatId, 9);
    Server::ServerCmd::WriteValueBySize(&bitBuf, nStatValue);
    if (nStatLayerOrCount < 0x100) {
      Fog::BitBuffer::WriteValueToBitBuffer(&bitBuf, 0, 1);
      nBitPos = 8;
    } else {
      Fog::BitBuffer::WriteValueToBitBuffer(&bitBuf, 1, 1);
      nBitPos = 0x10;
    }

    Fog::BitBuffer::WriteValueToBitBuffer(&bitBuf, (uint32_t)nStatLayerOrCount, nBitPos);
    nBitPos = Fog::BitBuffer::GetNextPositon(&bitBuf);
    aPacket[1] = (char)nBitPos + 2;
    SCMD_QueuePacketForClient(aPacket, 0x22, pClient);
}

